//! The lvim look — lvim-picker as it is drawn in Neovim, without Neovim.
//!
//! Every colour comes from a THEME FILE. The themes are generated by
//! lvim-colorscheme (`scripts/build lvim_fuzzy`), which resolves each role
//! through lvim-utils' own highlight factory, so the finder matches the
//! picker exactly. Nothing is computed here: a role missing from the theme
//! falls back to a neutral style, and the config can override any role.

use std::collections::HashMap;

use crossterm::style::{Attribute, Attributes, Color};

use crate::theme::Style;

/// The terminal's own colours, asked once (OSC 10/11/4) and cached. Only to be
/// called before the finder reads the keyboard: the replies arrive as input.
pub fn terminal_colors() -> Option<&'static crate::termcolors::TermColors> {
    static ASKED: std::sync::OnceLock<Option<crate::termcolors::TermColors>> = std::sync::OnceLock::new();
    ASKED.get_or_init(crate::termcolors::query).as_ref()
}

/// The difference in perceived lightness of two colours (0..255).
fn contrast(a: Color, b: Color) -> f64 {
    let lum = |c: Color| match c {
        Color::Rgb { r, g, b } => 0.2126 * r as f64 + 0.7152 * g as f64 + 0.0722 * b as f64,
        _ => 0.0,
    };
    (lum(a) - lum(b)).abs()
}

/// A background a step off `bg`: lighter on a dark one, darker on a light one.
pub fn shade(bg: Color) -> Color {
    let Color::Rgb { r, g, b } = bg else {
        return bg;
    };
    let lum = 0.2126 * r as f64 + 0.7152 * g as f64 + 0.0722 * b as f64;
    let toward = if lum < 128.0 { Color::Rgb { r: 255, g: 255, b: 255 } } else { Color::Rgb { r: 0, g: 0, b: 0 } };
    blend(toward, bg, 0.08)
}

/// lvim-utils `hl.blend(fg, bg, alpha)`, in doubles like Lua so the result is
/// byte-identical (rounding is `floor(x + 0.5)` there too).
pub fn blend(fg: Color, bg: Color, a: f64) -> Color {
    let rgb = |c: Color| match c {
        Color::Rgb { r, g, b } => (r as f64, g as f64, b as f64),
        _ => (0.0, 0.0, 0.0),
    };
    let (fr, fgc, fb) = rgb(fg);
    let (br, bgc, bb) = rgb(bg);
    let mix = |x: f64, y: f64| (x * a + y * (1.0 - a) + 0.5).floor().clamp(0.0, 255.0) as u8;
    Color::Rgb { r: mix(fr, br), g: mix(fgc, bgc), b: mix(fb, bb) }
}

/// The theme used when none is set: the terminal's own 16 colours, so the lvim
/// layout follows whatever theme the terminal has.
pub const TERMINAL: &str = "terminal";

#[derive(Clone, Debug)]
pub struct Theme {
    pub name: String,
    pub palette: HashMap<String, Color>,
    pub roles: HashMap<String, Style>,
}

fn hex(s: &str) -> Option<Color> {
    let h = s.trim().strip_prefix('#')?;
    if h.len() != 6 {
        return None;
    }
    let v = u32::from_str_radix(h, 16).ok()?;
    Some(Color::Rgb { r: (v >> 16) as u8, g: (v >> 8) as u8, b: v as u8 })
}

/// A role: `{ fg = "#..", bg = "#..", bold = true, ... }`.
pub fn parse_role(v: &toml::Value) -> Option<Style> {
    let t = v.as_table()?;
    let mut st = Style::default();
    let mut attrs = Attributes::default();
    for (k, v) in t {
        match (k.as_str(), v) {
            ("fg", toml::Value::String(s)) => st.fg = hex(s),
            ("bg", toml::Value::String(s)) => st.bg = hex(s),
            ("bold", toml::Value::Boolean(true)) => attrs.set(Attribute::Bold),
            ("italic", toml::Value::Boolean(true)) => attrs.set(Attribute::Italic),
            ("underline", toml::Value::Boolean(true)) => attrs.set(Attribute::Underlined),
            ("reverse", toml::Value::Boolean(true)) => attrs.set(Attribute::Reverse),
            _ => {}
        }
    }
    st.attrs = attrs;
    Some(st)
}

impl Theme {
    /// The terminal theme: the lvim roles computed from the terminal's OWN
    /// colours (asked once with OSC 10/11/4), blended exactly as lvim-utils
    /// blends them — so with an lvim palette in the terminal it matches the
    /// generated theme. Plain ANSI colours when the terminal does not answer.
    pub fn terminal() -> Theme {
        match terminal_colors() {
            Some(tc) => Theme::from_terminal(tc).unwrap_or_else(Theme::ansi),
            None => Theme::ansi(),
        }
    }

    /// The lvim roles from the terminal's colours, with lvim-utils' tint scale
    /// (config/ui.lua) and blend. None when a needed colour is not RGB.
    pub fn from_terminal(tc: &crate::termcolors::TermColors) -> Option<Theme> {
        let rgb = |c: Option<Color>| c.filter(|c| matches!(c, Color::Rgb { .. }));
        let p = &tc.palette;
        let bg = rgb(Some(tc.bg))?;
        let fg = rgb(Some(tc.fg))?;
        let red = rgb(p[1]).or(rgb(p[9]))?;
        let green = rgb(p[2]).or(rgb(p[10]))?;
        let yellow = rgb(p[3]).or(rgb(p[11]))?;
        let blue = rgb(p[4]).or(rgb(p[12]))?;
        let magenta = rgb(p[5]).or(rgb(p[13])).unwrap_or(red);
        let cyan = rgb(p[6]).or(rgb(p[14])).unwrap_or(blue);
        // bright black is the dim text; some palettes make it (almost) the
        // background, which would hide the hints, ghosts and counts
        let comment = rgb(p[8]).filter(|c| contrast(*c, bg) >= 40.0).unwrap_or_else(|| blend(fg, bg, 0.6));
        let orange = rgb(p[11]).filter(|c| *c != yellow).unwrap_or(yellow);
        let t = |c: Color, a: f64| Some(blend(c, bg, a));
        let st = |fg: Color, bg: Option<Color>, bold: bool| {
            let mut attrs = Attributes::default();
            if bold {
                attrs.set(Attribute::Bold);
            }
            Style { fg: Some(fg), bg, attrs, regular: false }
        };
        let palette: HashMap<String, Color> = [
            ("bg", bg),
            ("fg", fg),
            ("comment", comment),
            ("blue", blue),
            ("yellow", yellow),
            ("red", red),
            ("green", green),
            ("orange", orange),
            ("cyan", cyan),
            ("teal", cyan),
            ("magenta", magenta),
            ("purple", magenta),
        ]
        .into_iter()
        .map(|(k, c)| (k.to_string(), c))
        .collect();
        // tint scale: lvim-utils/lua/lvim-utils/config/ui.lua `tint`
        let roles: HashMap<String, Style> = [
            ("panel", Style { fg: Some(fg), ..Style::default() }),
            ("row_odd", st(yellow, t(yellow, 0.05), false)),
            ("row_even", st(yellow, t(yellow, 0.08), false)),
            ("sel_odd", st(yellow, t(yellow, 0.15), true)),
            ("sel_even", st(yellow, t(yellow, 0.15), true)),
            ("match", st(red, None, true)),
            ("marker", st(red, None, true)),
            ("prompt", st(blue, t(blue, 0.3), true)),
            ("input", st(blue, t(blue, 0.05), false)),
            ("caret", st(bg, Some(blue), false)),
            ("title", st(blue, t(blue, 0.2), true)),
            ("counter", st(green, t(green, 0.3), true)),
            ("count", st(comment, None, false)),
            ("border", st(blue, None, false)),
            ("file_bar", st(yellow, t(yellow, 0.3), false)),
            ("file_name", st(yellow, t(yellow, 0.4), true)),
            ("file_icon", st(yellow, t(yellow, 0.4), true)),
            ("file_dir", st(yellow, t(yellow, 0.3), false)),
            ("footer", st(blue, None, true)),
            ("footer_key", st(blue, t(blue, 0.3), true)),
            ("footer_label", st(yellow, t(yellow, 0.2), false)),
            ("footer_sep", st(blend(red, bg, 0.3), t(red, 0.6), true)),
            ("chevron", st(yellow, None, true)),
            ("help_key_odd", st(blue, t(blue, 0.1), true)),
            ("help_desc_odd", st(blue, t(blue, 0.05), false)),
            ("help_key_even", st(yellow, t(yellow, 0.1), true)),
            ("help_desc_even", st(yellow, t(yellow, 0.05), false)),
            ("popup", Style { fg: Some(fg), ..Style::default() }),
            ("popup_border", st(blue, None, false)),
            ("notify", Style { fg: Some(fg), ..Style::default() }),
            ("preview_match", st(red, None, true)),
            ("preview_focus", st(blue, t(blue, 0.2), true)),
            ("line_nr", st(blend(fg, bg, 0.25), None, false)),
            ("cursor_line", Style { bg: t(blue, 0.23), ..Style::default() }),
            ("normal", Style { fg: Some(fg), ..Style::default() }),
        ]
        .into_iter()
        .map(|(k, s)| (k.to_string(), s))
        .collect();
        Some(Theme { name: TERMINAL.to_string(), palette, roles })
    }

    /// The lvim layout in plain ANSI colours (0–15), for a terminal that does
    /// not say what its colours are.
    pub fn ansi() -> Theme {
        use Color::*;
        let st = |fg: Option<Color>, bg: Option<Color>, bold: bool| {
            let mut attrs = Attributes::default();
            if bold {
                attrs.set(Attribute::Bold);
            }
            Style { fg, bg, attrs, regular: false }
        };
        let palette: HashMap<String, Color> = [
            ("fg", Reset),
            ("comment", DarkGrey),
            ("blue", DarkBlue),
            ("yellow", DarkYellow),
            ("red", DarkRed),
            ("green", DarkGreen),
            ("orange", Yellow),
            ("cyan", DarkCyan),
            ("teal", DarkCyan),
            ("magenta", DarkMagenta),
            ("purple", Magenta),
        ]
        .into_iter()
        .map(|(k, c)| (k.to_string(), c))
        .collect();
        let roles: HashMap<String, Style> = [
            ("panel", st(None, None, false)),
            ("row_odd", st(None, None, false)),
            ("row_even", st(None, None, false)),
            ("sel_odd", st(Some(Black), Some(DarkYellow), true)),
            ("sel_even", st(Some(Black), Some(DarkYellow), true)),
            ("match", st(Some(DarkRed), None, true)),
            ("marker", st(Some(DarkRed), None, true)),
            ("prompt", st(Some(Black), Some(DarkBlue), true)),
            ("input", st(Some(DarkBlue), None, false)),
            ("caret", st(None, Some(DarkBlue), false)),
            ("title", st(Some(DarkBlue), None, true)),
            ("counter", st(Some(Black), Some(DarkGreen), true)),
            ("count", st(Some(DarkGrey), None, false)),
            ("border", st(Some(DarkBlue), None, false)),
            ("file_bar", st(Some(DarkYellow), None, false)),
            ("file_name", st(Some(Black), Some(DarkYellow), true)),
            ("file_icon", st(Some(Black), Some(DarkYellow), true)),
            ("file_dir", st(Some(Black), Some(DarkYellow), false)),
            ("footer", st(Some(DarkBlue), None, true)),
            ("footer_key", st(Some(Black), Some(DarkBlue), true)),
            // boxes, like the themes' tinted cells: the terminal palette has no tints,
            // so a box is black text on its accent
            ("footer_label", st(Some(Black), Some(DarkYellow), false)),
            ("footer_sep", st(Some(DarkRed), None, true)),
            ("chevron", st(Some(DarkYellow), None, true)),
            ("help_key_odd", st(Some(DarkBlue), None, true)),
            ("help_desc_odd", st(None, None, false)),
            ("help_key_even", st(Some(DarkYellow), None, true)),
            ("help_desc_even", st(None, None, false)),
            ("popup", st(None, None, false)),
            ("popup_border", st(Some(DarkBlue), None, false)),
            ("notify", st(None, None, false)),
            ("preview_match", st(Some(DarkRed), None, true)),
            ("preview_focus", st(Some(Black), Some(DarkBlue), true)),
            ("line_nr", st(Some(DarkGrey), None, false)),
            ("cursor_line", st(None, Some(DarkGrey), false)),
            ("normal", st(None, None, false)),
        ]
        .into_iter()
        .map(|(k, s)| (k.to_string(), s))
        .collect();
        Theme { name: TERMINAL.to_string(), palette, roles }
    }

    pub fn parse(text: &str) -> Result<Theme, String> {
        let doc: toml::Table = text.parse().map_err(|e| format!("theme: {e}"))?;
        let name = doc.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
        let mut palette = HashMap::new();
        if let Some(p) = doc.get("palette").and_then(|v| v.as_table()) {
            for (k, v) in p {
                if let Some(c) = v.as_str().and_then(hex) {
                    palette.insert(k.clone(), c);
                }
            }
        }
        let mut roles = HashMap::new();
        if let Some(r) = doc.get("roles").and_then(|v| v.as_table()) {
            for (k, v) in r {
                if let Some(s) = parse_role(v) {
                    roles.insert(k.clone(), s);
                }
            }
        }
        Ok(Theme { name, palette, roles })
    }

    /// `name` is a theme file stem (`LvimBase_dark`), its `name` field
    /// (`LvimBaseDark`) or a path to a theme file.
    pub fn load(name: &str) -> Result<Theme, String> {
        Theme::load_in(&theme_dirs(), name)
    }

    /// `load`, looking in `dirs` (in order) — a program with its own themes directory.
    pub fn load_in(dirs: &[std::path::PathBuf], name: &str) -> Result<Theme, String> {
        if name.eq_ignore_ascii_case(TERMINAL) {
            return Ok(Theme::terminal());
        }
        let p = std::path::Path::new(name);
        if p.is_file() {
            let text = std::fs::read_to_string(p).map_err(|e| format!("{}: {e}", p.display()))?;
            return Theme::parse(&text);
        }
        for dir in dirs {
            let f = dir.join(format!("{name}.toml"));
            if f.is_file() {
                let text = std::fs::read_to_string(&f).map_err(|e| format!("{}: {e}", f.display()))?;
                return Theme::parse(&text);
            }
            if let Ok(rd) = std::fs::read_dir(dir) {
                for e in rd.filter_map(Result::ok) {
                    if let Ok(text) = std::fs::read_to_string(e.path())
                        && let Ok(t) = Theme::parse(&text)
                        && t.name.eq_ignore_ascii_case(name)
                    {
                        return Ok(t);
                    }
                }
            }
        }
        if name.eq_ignore_ascii_case(TERMINAL) {
            return Ok(Theme::terminal());
        }
        let dirs = dirs.iter().map(|d| d.display().to_string()).collect::<Vec<_>>().join(", ");
        Err(format!("theme not found: {name} (looked in {dirs})"))
    }

    pub fn role(&self, name: &str) -> Style {
        self.roles.get(name).copied().unwrap_or_default()
    }

    pub fn color(&self, name: &str) -> Option<Color> {
        self.palette.get(name).copied()
    }

    /// Theme names found in the themes directories (plus "terminal").
    pub fn list() -> Vec<String> {
        let mut v = vec![TERMINAL.to_string()];
        for dir in theme_dirs() {
            if let Ok(rd) = std::fs::read_dir(dir) {
                for e in rd.filter_map(Result::ok) {
                    let p = e.path();
                    if p.extension().is_some_and(|x| x == "toml")
                        && let Some(s) = p.file_stem()
                    {
                        let s = s.to_string_lossy().into_owned();
                        if !v.contains(&s) {
                            v.push(s);
                        }
                    }
                }
            }
        }
        v.sort();
        v
    }
}

fn xdg(var: &str, fallback: &str) -> Option<std::path::PathBuf> {
    std::env::var(var)
        .ok()
        .filter(|s| !s.is_empty())
        .map(std::path::PathBuf::from)
        .or_else(|| std::env::var("HOME").ok().map(|h| std::path::Path::new(&h).join(fallback)))
}

/// The theme to draw with: `name` (from --theme / $LVIM_FUZZY_THEME / the
/// config's `theme`), or the terminal's colours. A missing or broken theme is
/// never an error: it falls back, with a note to show.
pub fn resolve_theme(name: Option<&str>) -> (Theme, Option<String>) {
    resolve_theme_in(&theme_dirs(), name)
}

/// `resolve_theme`, looking in `dirs`.
pub fn resolve_theme_in(dirs: &[std::path::PathBuf], name: Option<&str>) -> (Theme, Option<String>) {
    match name {
        None => (Theme::terminal(), None),
        Some(n) => match Theme::load_in(dirs, n) {
            Ok(t) => (t, None),
            Err(e) => (Theme::terminal(), Some(format!("{e} — using the terminal's colours"))),
        },
    }
}

/// Where themes live: ~/.config/lvim-fuzzy/themes/<Name>.toml (as secmon /
/// keyforge). themer puts them there: it fetches lvim-colorscheme's
/// extras/lvim_fuzzy/<Name>.toml on every theme switch and sets `theme` in the
/// config.
pub fn theme_dirs() -> Vec<std::path::PathBuf> {
    config_dir().map(|c| vec![c.join("themes")]).unwrap_or_default()
}

/// The config directory of lvim-fuzzy (~/.config/lvim-fuzzy).
pub fn config_dir() -> Option<std::path::PathBuf> {
    xdg("XDG_CONFIG_HOME", ".config").map(|c| c.join("lvim-fuzzy"))
}

/// Every element of the lvim finder, resolved from the theme's roles.
#[derive(Clone, Debug)]
pub struct Look {
    pub panel: Style,
    pub rows: [Style; 2],
    pub sel: [Style; 2],
    pub matched: Style,
    pub marker: Style,
    pub prompt: Style,
    pub input: Style,
    pub caret: Style,
    pub title: Style,
    pub counter: Style,
    pub count: Style,
    pub border: Style,
    pub file_bar: Style,
    pub file_name: Style,
    pub file_icon: Style,
    pub file_dir: Style,
    pub footer_key: Style,
    pub footer_label: Style,
    pub chevron: Style,
    pub help_key: [Style; 2],
    pub help_desc: [Style; 2],
    pub popup: Style,
    pub popup_border: Style,
    pub preview_match: Style,
    pub preview_focus: Style,
    pub line_nr: Style,
    pub cursor_line: Style,
    /// The thumb of the list's scrollbar and of the preview's: each a role of the theme (`scrollbar`, `preview_scrollbar`), the theme's blue when it
    /// has none.
    pub scrollbar: Style,
    pub preview_scrollbar: Style,
    pub theme: Theme,
}

impl Look {
    pub fn new(t: Theme) -> Look {
        // a role the theme lacks falls back to the terminal theme's (never fail on a theme)
        let term = Theme::terminal();
        let r = |n: &str| t.roles.get(n).copied().unwrap_or_else(|| term.role(n));
        // a role the theme may leave out, that is then the theme's blue (a thumb of a scrollbar)
        let blue = Style { fg: t.color("blue").or_else(|| term.color("blue")), ..Style::default() };
        let bar = |n: &str| t.roles.get(n).copied().unwrap_or(blue);
        let panel = r("panel");
        // roles drawn on the panel take its background when they set none
        let on_panel = |s: Style| Style { bg: s.bg.or(panel.bg), ..s };
        Look {
            rows: [r("row_odd"), r("row_even")],
            sel: [r("sel_odd"), r("sel_even")],
            matched: r("match"),
            marker: r("marker"),
            prompt: r("prompt"),
            input: r("input"),
            caret: r("caret"),
            title: r("title"),
            counter: r("counter"),
            count: on_panel(r("count")),
            border: on_panel(r("border")),
            file_bar: r("file_bar"),
            file_name: r("file_name"),
            file_icon: r("file_icon"),
            file_dir: r("file_dir"),
            footer_key: r("footer_key"),
            footer_label: r("footer_label"),
            chevron: on_panel(r("chevron")),
            help_key: [r("help_key_odd"), r("help_key_even")],
            help_desc: [r("help_desc_odd"), r("help_desc_even")],
            popup: r("popup"),
            popup_border: r("popup_border"),
            preview_match: r("preview_match"),
            preview_focus: r("preview_focus"),
            line_nr: on_panel(r("line_nr")),
            cursor_line: r("cursor_line"),
            scrollbar: on_panel(bar("scrollbar")),
            preview_scrollbar: on_panel(bar("preview_scrollbar")),
            panel,
            theme: t,
        }
    }
}

/// A file icon (Nerd Font) and the palette role it wears, from lvim-icons'
/// data (src/icons.rs): the exact file name, then the extension (the longest
/// dotted tail first: `test.tsx` before `tsx`), then the generic file.
pub fn icon(path: &str, is_dir: bool) -> (&'static str, &'static str) {
    use crate::icons::{DIRECTORY, EXTENSIONS, FILE, FILENAMES};
    if is_dir {
        return DIRECTORY;
    }
    let find = |table: &'static [(&str, &str, &str)], key: &str| table.binary_search_by(|(k, _, _)| (*k).cmp(key)).ok().map(|i| (table[i].1, table[i].2));
    let name = path.trim_end_matches('/').rsplit('/').next().unwrap_or(path);
    if let Some(hit) = find(FILENAMES, name) {
        return hit;
    }
    let lower = name.to_ascii_lowercase();
    let mut at = 0;
    while let Some(p) = lower[at..].find('.') {
        let tail = &lower[at + p + 1..];
        if let Some(hit) = find(EXTENSIONS, tail) {
            return hit;
        }
        at += p + 1;
    }
    FILE
}

/// The field of a search prompt: a tint of the badge's own background, paler than it.
pub fn search_field(l: &Look) -> Style {
    // (half way back to the field's own tint: paler than the badge)
    let bg = match (l.prompt.bg, l.input.bg) {
        (Some(p), Some(i)) => Some(blend(p, i, 0.5)),
        (p, i) => p.or(i),
    };
    Style { bg, ..l.input }
}

/// The badge of a search prompt (the magnifier): on the field's own background — the bar is one tone, the magnifier only differs by its colour.
pub fn search_badge_style(l: &Look) -> Style {
    Style { bg: search_field(l).bg, ..l.prompt }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_a_generated_theme() {
        let t = Theme::parse(
            r##"name = "LvimBaseDark"
[palette]
blue = "#447ca2"
[roles]
panel = { fg = "#5e8888", bg = "#1c2327" }
row_odd = { fg = "#d8b36f", bg = "#292e2e" }
sel_odd = { fg = "#d8b36f", bg = "#3c3c35", bold = true }
count = { fg = "#5b7d7e" }
"##,
        )
        .unwrap();
        assert_eq!(t.name, "LvimBaseDark");
        assert_eq!(t.role("row_odd").bg, hex("#292e2e"));
        assert!(t.role("sel_odd").attrs.has(Attribute::Bold));
        assert_eq!(t.color("blue"), hex("#447ca2"));
        let look = Look::new(t);
        // `count` sets only fg: it takes the panel background
        assert_eq!(look.count.bg, look.panel.bg);
    }

    #[test]
    fn terminal_tints_match_the_generated_theme() {
        // the terminal set to LvimBase_dark's palette → the generated theme's roles
        let h = |s: &str| hex(s).unwrap();
        let mut palette = [None; 16];
        for (i, c) in [(1, "#d75e52"), (2, "#7e965a"), (3, "#d8b36f"), (4, "#447ca2"), (8, "#5b7d7e")] {
            palette[i] = Some(h(c));
        }
        let tc = crate::termcolors::TermColors { fg: h("#5e8888"), bg: h("#20272b"), palette };
        let t = Theme::from_terminal(&tc).unwrap();
        // values from lvim-colorscheme's extras/lvim_fuzzy/LvimBase_dark.toml
        assert_eq!(t.role("row_odd").bg, hex("#292e2e"));
        assert_eq!(t.role("row_even").bg, hex("#2f3230"));
        assert_eq!(t.role("sel_odd").bg, hex("#3c3c35"));
        assert_eq!(t.role("prompt").bg, hex("#2b414f"));
        assert_eq!(t.role("input").bg, hex("#222b31"));
        assert_eq!(t.role("title").bg, hex("#273843"));
        assert_eq!(t.role("counter").bg, hex("#3c4839"));
        assert_eq!(t.role("footer_key").bg, hex("#2b414f"));
        assert_eq!(t.role("footer_label").bg, hex("#454339"));
        assert_eq!(t.role("file_name").bg, hex("#6a5f46"));
    }

    #[test]
    fn dim_text_stays_readable() {
        // a palette whose bright black is almost the background (kitty's everforest)
        let rgb = |s: &str| {
            let v = u32::from_str_radix(&s[1..], 16).unwrap();
            Color::Rgb { r: (v >> 16) as u8, g: (v >> 8) as u8, b: v as u8 }
        };
        let mut palette = [None; 16];
        for (i, c) in ["#1c2121", "#cb4f4f", "#75783a", "#af9e6b", "#3a6479", "#bb755e", "#527a57", "#677163", "#2d3331"].iter().enumerate() {
            palette[i] = Some(rgb(c));
        }
        let tc = crate::termcolors::TermColors { fg: rgb("#96a990"), bg: rgb("#212626"), palette };
        let t = Theme::from_terminal(&tc).unwrap();
        let count = t.role("count").fg.unwrap();
        assert!(contrast(count, rgb("#212626")) >= 40.0, "{count:?}");
    }

    #[test]
    fn terminal_theme_needs_no_file() {
        let t = Theme::load("terminal").unwrap();
        assert_eq!(t.name, "terminal");
        assert_eq!(t.role("panel").bg, None); // the terminal's own background
        assert!(Theme::list().contains(&"terminal".to_string()));
    }
}
